 		);
 	};

+	onSelectPlanOwner = user => {
+		const { translate } = this.props;
+
+		accept(
+			translate(
+				'Are you absolutely sure you want to change the plan purchaser for this site to {{user /}}?',
+				{
+					components: {
+						user: <strong>{ user.display_name || user.name }</strong>,
+					},
