+			accepted => {
+				if ( accepted ) {
+					this.props.transferPlanOwnership( this.props.siteId, user.linked_user_ID );
+					this.props.recordTracksEvent( 'calypso_jetpack_plan_ownership_changed' );
+				}
+			},
+			translate( 'Yes, change the plan purchaser' ),
